 {Fixture x;x.eat(2);auto p=x.spawn(4);x.w(p+0x180,0);t::enter_room(162);need(t::snapshot().tree==0 && t::snapshot().fruitActors[3]==p,"room change clears tree allocation but preserves carried fruit provenance");need(t::snapshot().consumedmask==2 && t::snapshot().totalConsumed==1,"room change preserves consumed slots");t::enter_room(83);for(unsigned i=0;i<6;++i)x.w(Fixture::priv+i*4,0);x.init();need(x.h(Fixture::priv+0x20)==0,"eaten fruit remains absent on revisit");need(x.h(Fixture::priv+0x24)==0,"unconsumed carried fruit cannot duplicate on revisit");t::forget(p);t::frame(x.rdram);need(x.h(Fixture::priv+0x24)==1,"unconsumed actually retired fruit can reappear");need(t::snapshot().regenerations==0,"room roundtrip does not regenerate");}
