 {Fixture x;auto p=x.spawn(5);x.w(p+0x180,0);t::forget(Fixture::tree);need(t::snapshot().fruitActors[4]==p,"tree teardown preserves independently carried fruit token");const auto before=x.mem;x.call("func_80573F94",p);need(t::snapshot().totalConsumed==1 && t::snapshot().consumedmask==16,"carried fruit collection remains attributable after tree teardown");need(x.mem==before,"collection after tree disposal writes no stale private allocation");x.init();need(x.h(Fixture::priv+0x26)==0,"same-room tree rebind retains consumed carried slot");}
 {Fixture x;for(unsigned batch=0;batch<3;batch++){t::enter_room(83);for(unsigned i=0;i<6;i++)x.w(Fixture::priv+i*4,0);x.init();std::array<uint32_t,5> carried{};for(unsigned i=1;i<=5;i++){carried[i-1]=x.spawn(i);x.w(carried[i-1]+0x180,0);}t::enter_room(162);const auto before=x.mem;for(auto p:carried)x.call("func_80573F94",p);need(x.mem==before,"whole carried batch collected outside rest has no native writes");need(t::snapshot().totalConsumed==(batch+1)*5 && t::snapshot().regenerations==std::min(batch+1,2u),"global two-regeneration quota preserved across repeated room changes");need(t::ledger_valid(),"global ledger remains arithmetically valid");for(auto p:carried)x.call("func_80573F94",p);need(t::snapshot().totalConsumed==(batch+1)*5,"old batch callbacks cannot earn a new supply");}t::enter_room(83);for(unsigned i=0;i<6;i++)x.w(Fixture::priv+i*4,0);x.init();for(unsigned i=0;i<6;i++)need(x.h(Fixture::priv+0x1C+i*2)==0,"all native slots including heart exhausted after fifteen actual fruits");need(t::snapshot().totalConsumed==t::max_consumed && t::snapshot().regenerations==t::max_regenerations,"fifteen session fruits and two global replenishments maximum");}
 {Fixture x;auto p=x.spawn(1);x.w(p+0x180,0);t::enter_room(162);t::forget(p);x.actor(p,t::kinds[1]);x.call("func_80573F94",p);need(t::snapshot().totalConsumed==0,"carried token forget protects against same-kind reuse in another room");}
 {Fixture x;auto p=x.spawn(1);x.w(p+0x180,0);t::enter_room(162);x.w(p,0);const auto before=x.mem;t::frame(x.rdram);need(t::snapshot().fruitActors[0]==0,"outside-rest frame prunes dead token without a native write");need(x.mem==before,"outside-room lifetime pruning is read-only");}
