 for(unsigned queue:{0u,1u,2u}){Fixture x;const auto p=x.spawn(2);x.w(p+0x180,0);x.by(p+0x17D,queue);t::enter_room(162);t::frame(x.rdram);need(t::snapshot().fruitActors[1]==p,"Live detached queue0/1/2 keeps its token across rooms");x.call("func_80573F94",p);need(t::snapshot().totalConsumed==1 && t::snapshot().consumedmask==2,"Live carried fruit consumes its original slot exactly once");}
 {Fixture x;x.eat(1);const auto p=x.spawn(2);x.by(p+0x17D,3);t::frame(x.rdram);need(x.h(Fixture::priv+0x1E)==0 && x.h(Fixture::priv+0x20)==1,"Retired unconsumed slot reopens while eaten slot remains spent");need(t::snapshot().totalConsumed==1 && t::snapshot().regenerations==0 && t::ledger_valid(),"Pruning never resets the user's consumed1/regeneration0 ledger");}
 {Fixture x;x.eat(1);for(unsigned i=2;i<=5;++i)x.spawn(i);x.init();need(x.h(Fixture::priv+0x20)==0,"Repeated setter keeps real current attached fruit bound");t::enter_room(162);t::enter_room(83);for(unsigned i=0;i<6;++i)x.w(Fixture::priv+i*4,0);x.init();need(t::snapshot().totalConsumed==1 && t::snapshot().regenerations==0 && t::snapshot().consumedmask==1,"Tree rebind preserves the user's exact consumed1/regeneration0 ledger");need(x.h(Fixture::priv+0x1E)==0,"Genuinely eaten fruit remains spent");for(unsigned i=2;i<=5;++i)need(x.h(Fixture::priv+0x1C+2*i)==1 && t::snapshot().fruitActors[i-1]==0,"Old tree-attached live typed tokens cannot suppress the new native tree");}
